import React, { useState } from "react";
import { useAuthorize } from "../context/hook/useAuthorization";
import { Button, Form, Input, Select, notification } from 'antd';
import NavMenu from "./SharedComponents/navMenu";
import '../styles/myaccount.css';

const { Option } = Select;

const AddWorkspace = () => {
    const { userAccount } = useAuthorize();
    const [form] = Form.useForm();

    const handleSubmit = async (values) => {
        try {
            const response = await fetch('/api/workspaces/add', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${userAccount.userToken}`
                },
                body: JSON.stringify(values)
            });
            const data = await response.json();
            if (response.ok) {
                notification.success({
                    message: 'Success',
                    description: 'Workspace added successfully.'
                });
                form.resetFields();
            } else {
                throw new Error(data.error || 'Failed to add workspace');
            }
        } catch (error) {
            notification.error({
                message: 'Error',
                description: error.message || 'Failed to add workspace due to an error.'
            });
        }
    };

    return (
        <div className="add-workspace">
            <NavMenu isAdmin={true} breadcrum="Add Workspace" pagePath="/add-workspace" />
            <Form form={form} layout="vertical" onFinish={handleSubmit}>
                <Form.Item
                    name="name"
                    label="Workspace Name"
                    rules={[{ required: true, message: 'Please input the workspace name!' }]}
                >
                    <Input placeholder="Enter workspace name" />
                </Form.Item>
                <Form.Item
                    name="location"
                    label="Location"
                    rules={[{ required: true, message: 'Please input the location of the workspace!' }]}
                >
                    <Input placeholder="Enter workspace location" />
                </Form.Item>
                <Form.Item
                    name="status"
                    label="Status"
                    initialValue="available"
                >
                    <Select>
                        <Option value="available">Available</Option>
                        <Option value="unavailable">Unavailable</Option>
                    </Select>
                </Form.Item>
                <Form.Item>
                    <Button type="primary" htmlType="submit">
                        Add Workspace
                    </Button>
                </Form.Item>
            </Form>
        </div>
    );
};

export default AddWorkspace;
